"""Route path matching and dictionary consolidation."""
from typing import Dict, Any, List

def deep_merge_matchers(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    res = dict(base)
    for k, v in override.items():
        if k in res and isinstance(res[k], dict) and isinstance(v, dict):
            res[k] = deep_merge_matchers(res[k], v)
        elif k in res and isinstance(res[k], list) and isinstance(v, list):
            # Rule H12: concatenate lists in order of [base_items + override_items]
            # with duplicate items removed while preserving first-seen order.
            merged_list = []
            seen_items = set()

            # Add items from the base list first
            for item in res[k]:
                if item not in seen_items:
                    merged_list.append(item)
                    seen_items.add(item)

            # Then add items from the override list, skipping duplicates already seen
            for item in v:
                if item not in seen_items:
                    merged_list.append(item)
                    seen_items.add(item)

            res[k] = merged_list
        else:
            # For other types or if types don't match, override the base value
            res[k] = v
    return res

def normalize_prefix(path: str) -> str:
    return "/" + path.strip("/")
